    save_json(majors, 'majors.json')
    print(f"\n共 {len(majors)} 个专业")
    
    # ==================== 录取分数数据 ====================
    scores = []
    
    # 为每所高校生成在河南的录取分数
    for college in colleges[:100]:  # 取前100所高校生成录取分数
        college_id = college['id']
        college_name = college['name']
        
        # 根据高校层次设置基准分数
        rank = college.get('rankings', {}).get('comprehensive', 100)
        
        if rank <= 10:
            base_score_science = 680 - rank * 5
        elif rank <= 50:
            base_score_science = 630 - (rank - 10) * 3
        elif rank <= 100:
            base_score_science = 580 - (rank - 50) * 2
        else:
            base_score_science = max(450, 530 - (rank - 100))
        
        # 2024年数据
        for year in [2024, 2023, 2022]:
            year_diff = 2024 - year
            score_year = base_score_science - year_diff * 2
            
            scores.append({
                "college_id": college_id,
                "college_name": college_name,
                "major_name": "计算机科学与技术",
                "year": year,
                "batch": "本科一批",
                "category": "理科",
                "score": score_year,
                "rank_min": int(score_year * 100 - 5000),
                "rank_max": int(score_year * 100 - 6000)
            })
            
            scores.append({
                "college_id": college_id,
                "college_name": college_name,
                "major_name": "电子信息工程",
                "year": year,
                "batch": "本科一批",
                "category": "理科",
                "score": score_year - 5,
                "rank_min": int(score_year * 100 - 4000),
                "rank_max": int(score_year * 100 - 5000)
            })
            
            if rank <= 50:
                scores.append({
                    "college_id": college_id,
                    "college_name": college_name,
                    "major_name": "临床医学",
                    "year": year,
                    "batch": "本科一批",
                    "category": "理科",
                    "score": score_year - 10,
                    "rank_min": int(score_year * 100 - 3000),
                    "rank_max": int(score_year * 100 - 4000)
                })
    
    # 添加河南省高校二批数据
    for college in colleges[100:150]:
        college_id = college['id']
        college_name = college['name']
        
        for year in [2024, 2023]:
            scores.append({
                "college_id": college_id,
                "college_name": college_name,
                "major_name": "计算机科学与技术",
                "year": year,
                "batch": "本科二批",
                "category": "理科",
                "score": 500 - (year - 2024) * 3,
                "rank_min": 100000,
                "rank_max": 80000
            })
    
    save_json(scores, 'scores.json')
    print(f"\n共 {len(scores)} 条录取分数记录")
    
    # ==================== 排名数据 ====================
    rankings = []
    
    for i, college in enumerate(colleges[:100]):
        rankings.append({
            "year": 2024,
            "ranking_type": "comprehensive",
            "college_id": college['id'],
            "college_name": college['name'],
            "rank": i + 1,
            "score": max(100 - i * 0.5, 60)
        })
    
    save_json(rankings, 'rankings.json')
    print(f"\n共 {len(rankings)} 条排名记录")
    
